 723	// restoreFromCommittedLogs recovers the Raft node from committed logs.
 724	func (r *Raft) restoreFromCommittedLogs() error {
 725		if !r.RestoreCommittedLogs {
 726			return nil
 727		}
 728	
 729		// If the store implements CommitTrackingLogStore, we can read the commit index from the store.
 730		// This is useful when the store is able to track the commit index and we can avoid replaying logs.
 731		store, ok := r.logs.(CommitTrackingLogStore)
 732		if !ok {
 733			r.logger.Warn("restore committed logs enabled but log store does not support it", "log_store", fmt.Sprintf("%T", r.logs))
 734			return ErrIncompatibleLogStore
 735		}
 736	
 737		commitIndex, err := store.GetCommitIndex()
 738		if err != nil {
 739			r.logger.Error("failed to get commit index from store", "error", err)
 740			return err
 741		}
 742	
 743		lastIndex, err := r.logs.LastIndex()
 744		if err != nil {
 745			r.logger.Error("failed to get last log index from store", "error", err)
 746			return err
 747		}
 748		if commitIndex > lastIndex {
 749			commitIndex = lastIndex
 750		}
 751	
 752		r.setCommitIndex(commitIndex)
 753		r.processLogs(commitIndex, nil)
 754		return nil
 755	}
